/**
 * 📘 1-1 斐波那契数列
 *
 * 问题：计算斐波那契数列的第 n 项。
 *   F(0) = 0, F(1) = 1
 *   F(n) = F(n-1) + F(n-2)
 *
 * 学这个的目的：DP 的 Hello World。
 * 展示 DP 的三个核心要素：
 *   ① 状态定义 —— dp[i] 表示第 i 个斐波那契数
 *   ② 状态转移方程 —— dp[i] = dp[i-1] + dp[i-2]
 *   ③ 边界条件 —— dp[0] = 0, dp[1] = 1
 *
 * 先做对比实验：暴力递归 vs 记忆化 vs DP，感受速度差异。
 *
 * ────────────────────────────────────────────────────
 */

// ─── 方法 1：暴力递归（指数级） ─────────────────────
// fib(45) 跑 5~15 秒，fib(50) 数分钟
function fibBrute(n: number): number {
  if (n <= 1) return n;
  return fibBrute(n - 1) + fibBrute(n - 2);
}
// 原因：重复计算了巨量子问题

// ─── 方法 2：记忆化递归（自顶向下） ─────────────────
// 用缓存存算过的结果
function fibMemo(n: number, memo: number[] = []): number {
  if (n <= 1) return n;
  if (memo[n] !== undefined) return memo[n];
  memo[n] = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
  return memo[n];
}

// ─── 方法 3：自底向上 DP ───────────────────────────
// 从小到大填表
function fibDp(n: number): number {
  if (n <= 1) return n;
  const dp: number[] = [0, 1];
  for (let i = 2; i <= n; i++) {
    dp[i] = dp[i - 1] + dp[i - 2];
  }
  return dp[n];
}

// ─── 方法 4：空间优化 DP ──────────────────────────
// 只存前两个值，O(1) 空间
function fibOpt(n: number): number {
  if (n <= 1) return n;
  let prev2 = 0, prev1 = 1;
  for (let i = 2; i <= n; i++) {
    const cur = prev1 + prev2;
    prev2 = prev1;
    prev1 = cur;
  }
  return prev1;
}

// ─── 测试 ─────────────────────────────────────────
const N = 45;
console.log('=== 对比实验：为什么 DP 比暴力递归快？ ===\n');

console.time('② 记忆化递归');
console.log('fibMemo(45) =', fibMemo(N));
console.timeEnd('② 记忆化递归');

console.time('③ 自底向上 DP');
console.log('fibDp(45)   =', fibDp(N));
console.timeEnd('③ 自底向上 DP');

console.time('④ 空间优化 DP');
console.log('fibOpt(45)  =', fibOpt(N));
console.timeEnd('④ 空间优化 DP');

console.log('\n① 暴力递归没跑——指数爆炸 O(2ⁿ)');
console.log('结论：DP = 空间换时间，消除重复计算');

/**
 * 📘 1-2 爬楼梯
 *
 * 问题：一次可以爬 1 阶或 2 阶，爬到 n 阶有多少种方法？
 *
 * 思路：最后一步要么从 n-1 跨 1 阶，要么从 n-2 跨 2 阶。
 *   dp[i] = dp[i-1] + dp[i-2]
 *   边界：dp[1] = 1, dp[2] = 2
 *
 * 扩展：如果一次可以爬 1,2,3 阶？
 *   dp[i] = dp[i-1] + dp[i-2] + dp[i-3]
 *
 * ────────────────────────────────────────────────────
 */

// ─── 基础 DP ──────────────────────────────────────
function climbStairs(n: number): number {
  if (n <= 2) return n;
  const dp: number[] = [];
  dp[0] = 0;
  dp[1] = 1;
  dp[2] = 2;
  for (let i = 3; i <= n; i++) {
    dp[i] = dp[i - 1] + dp[i - 2];
  }
  return dp[n];
}

// ─── 空间优化 ─────────────────────────────────────
function climbStairsOpt(n: number): number {
  if (n <= 2) return n;
  let prev2 = 1, prev1 = 2;
  for (let i = 3; i <= n; i++) {
    const cur = prev1 + prev2;
    prev2 = prev1;
    prev1 = cur;
  }
  return prev1;
}

// ─── 扩展：可爬 1,2,3 阶 ──────────────────────────
function climbStairs3(n: number): number {
  if (n <= 1) return n;
  if (n === 2) return 2;
  if (n === 3) return 4;
  const dp: number[] = [];
  dp[1] = 1; dp[2] = 2; dp[3] = 4;
  for (let i = 4; i <= n; i++) {
    dp[i] = dp[i - 1] + dp[i - 2] + dp[i - 3];
  }
  return dp[n];
}

// ─── 测试 ─────────────────────────────────────────
console.log('=== 爬楼梯 ===\n');
for (let n = 1; n <= 10; n++) {
  console.log(`${n} 阶 → ${climbStairs(n)} 种方法`);
}
console.log('\n--- 扩展（1,2,3 步）---');
for (let n = 1; n <= 10; n++) {
  console.log(`${n} 阶 → ${climbStairs3(n)} 种方法`);
}

/**
 * 📘 1-3 最小花费爬楼梯
 *
 * 问题：每阶楼梯有 cost[i]，从 i 阶往上爬需付 cost[i]。
 * 可从第 0 或第 1 阶开始，每次爬 1 或 2 阶。求到楼顶的最小花费。
 *
 * 思路：
 *   dp[i] = 到达 i 阶的最小总花费（含本阶 cost）
 *   dp[i] = min(dp[i-1], dp[i-2]) + cost[i]
 *   最终答案 = min(dp[n-1], dp[n-2])  —— 楼顶在 n 阶之后，不需再出发
 *
 * 从"计数"到"求最值"的转折点。
 *
 * ─── LeetCode 746 ─────────────────────────────────
 */

function minCostClimbingStairs(cost: number[]): number {
  const n = cost.length;
  if (n === 2) return Math.min(cost[0], cost[1]);
  const dp: number[] = [];
  dp[0] = cost[0];
  dp[1] = cost[1];
  for (let i = 2; i < n; i++) {
    dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
  }
  return Math.min(dp[n - 1], dp[n - 2]);
}

// ─── 空间优化 ─────────────────────────────────────
function minCostClimbingStairsOpt(cost: number[]): number {
  const n = cost.length;
  if (n === 2) return Math.min(cost[0], cost[1]);
  let prev2 = cost[0], prev1 = cost[1];
  for (let i = 2; i < n; i++) {
    const cur = Math.min(prev1, prev2) + cost[i];
    prev2 = prev1;
    prev1 = cur;
  }
  return Math.min(prev1, prev2);
}

// ─── 测试 ─────────────────────────────────────────
console.log('=== 最小花费爬楼梯 ===\n');
const cases = [
  [10, 15, 20],
  [1, 100, 1, 1, 1, 100, 1, 1, 100, 1],
];
for (const cost of cases) {
  console.log(`cost = [${cost}] → ${minCostClimbingStairs(cost)}`);
}

/**
 * 📐 2-1 唯一路径数（Unique Paths）
 *
 * 问题：m×n 网格，从左上走到右下，只能向右或向下，有多少条路？
 *
 * 思路：
 *   到 (i,j) 的最后一步要么从 (i-1,j) 向下，要么从 (i,j-1) 向右。
 *   dp[i][j] = dp[i-1][j] + dp[i][j-1]
 *   边界：第一行和第一列都只有 1 种走法
 *
 * 学习点：一维 DP → 二维 DP 的第一次跨越。
 * 空间优化技巧：滚动数组（一维数组行行更新）
 *
 * ────────────────────────────────────────────────────
 */

// ─── 二维 DP ──────────────────────────────────────
function uniquePaths(m: number, n: number): number {
  const dp: number[][] = Array.from({ length: m }, () => Array(n).fill(0));
  for (let j = 0; j < n; j++) dp[0][j] = 1;
  for (let i = 0; i < m; i++) dp[i][0] = 1;
  for (let i = 1; i < m; i++) {
    for (let j = 1; j < n; j++) {
      dp[i][j] = dp[i - 1][j] + dp[i][j - 1];
    }
  }
  return dp[m - 1][n - 1];
}

// ─── 空间优化：滚动数组 ───────────────────────────
function uniquePathsOpt(m: number, n: number): number {
  const dp: number[] = Array(n).fill(1);
  for (let i = 1; i < m; i++) {
    for (let j = 1; j < n; j++) {
      dp[j] = dp[j] + dp[j - 1];
    }
  }
  return dp[n - 1];
}

// ─── 测试 ─────────────────────────────────────────
console.log('=== 唯一路径数 ===\n');
const tests: [number, number][] = [
  [3, 7],
  [3, 2],
  [3, 3],
  [1, 1],
];
for (const [m, n] of tests) {
  console.log(
    `${m}×${n} → ${uniquePaths(m, n)}（空间优化: ${uniquePathsOpt(m, n)}）`
  );
}

/**
 * 📐 2-2 最小路径和（Minimum Path Sum）
 *
 * 问题：m×n 网格，每个格子有非负整数，找左上到右下的路径，
 * 只能向右或向下，使路径数字之和最小。
 *
 * 思路：
 *   dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]
 *   边界：第一行只能从左来，第一列只能从上面来
 *
 * 学习点："计数"→"求最值"的二维版本。
 * 和 爬楼梯 → 最小花费爬楼梯 是同一思路升级。
 *
 * ─── LeetCode 64 ─────────────────────────────────
 */

function minPathSum(grid: number[][]): number {
  const m = grid.length, n = grid[0].length;
  const dp: number[][] = Array.from({ length: m }, () => Array(n).fill(0));
  dp[0][0] = grid[0][0];
  for (let j = 1; j < n; j++) dp[0][j] = dp[0][j - 1] + grid[0][j];
  for (let i = 1; i < m; i++) dp[i][0] = dp[i - 1][0] + grid[i][0];
  for (let i = 1; i < m; i++) {
    for (let j = 1; j < n; j++) {
      dp[i][j] = Math.min(dp[i - 1][j], dp[i][j - 1]) + grid[i][j];
    }
  }
  return dp[m - 1][n - 1];
}

// ─── 空间优化 ─────────────────────────────────────
function minPathSumOpt(grid: number[][]): number {
  const m = grid.length, n = grid[0].length;
  const dp: number[] = Array(n).fill(0);
  dp[0] = grid[0][0];
  for (let j = 1; j < n; j++) dp[j] = dp[j - 1] + grid[0][j];
  for (let i = 1; i < m; i++) {
    dp[0] = dp[0] + grid[i][0];
    for (let j = 1; j < n; j++) {
      dp[j] = Math.min(dp[j], dp[j - 1]) + grid[i][j];
    }
  }
  return dp[n - 1];
}

// ─── 测试 ─────────────────────────────────────────
console.log('=== 最小路径和 ===\n');
const grid1 = [[1,3,1],[1,5,1],[4,2,1]];
console.log('网格:', grid1);
console.log('最小路径和:', minPathSum(grid1), '(期望 7)');

/**
 * 🎒 3-1 0/1 背包问题
 *
 * 问题：N 个物品，每个重 w[i]、价值 v[i]。背包容量 C，每种最多选 1 个。
 * 求最大总价值。
 *
 * 思路：
 *   dp[i][c] = 前 i 个物品，容量 c 时的最大价值
 *   不选 i: dp[i-1][c]
 *   选 i:   dp[i-1][c-w[i]] + v[i]（前提 c >= w[i]）
 *   取二者 max
 *
 * 学习点：这是 DP 最重要的模型。选/不选决策 + 容量维度。
 * 空间优化关键：容量倒序遍历（防止重复选）
 *
 * ────────────────────────────────────────────────────
 */

// ─── 二维 DP ──────────────────────────────────────
function knapsack01(weights: number[], values: number[], capacity: number): number {
  const n = weights.length;
  const dp: number[][] = Array.from({ length: n + 1 }, () => Array(capacity + 1).fill(0));
  for (let i = 1; i <= n; i++) {
    const w = weights[i - 1], v = values[i - 1];
    for (let c = 0; c <= capacity; c++) {
      dp[i][c] = dp[i - 1][c];
      if (c >= w) dp[i][c] = Math.max(dp[i][c], dp[i - 1][c - w] + v);
    }
  }
  return dp[n][capacity];
}

// ─── 空间优化（一维，容量倒序） ────────────────────
function knapsack01Opt(weights: number[], values: number[], capacity: number): number {
  const dp: number[] = Array(capacity + 1).fill(0);
  for (let i = 0; i < weights.length; i++) {
    const w = weights[i], v = values[i];
    for (let c = capacity; c >= w; c--) {
      dp[c] = Math.max(dp[c], dp[c - w] + v);
    }
  }
  return dp[capacity];
}

// ─── 测试 ─────────────────────────────────────────
console.log('=== 0/1 背包 ===\n');
const weights = [2, 3, 4, 5], values = [3, 4, 5, 6];
for (const cap of [5, 8, 10]) {
  console.log(`容量 ${cap}: 最大价值 = ${knapsack01(weights, values, cap)}`);
}

/**
 * ============================================================
 * 📘 3-1 0/1 背包问题
 * ============================================================
 *
 * 问题：有 N 个物品，每个物品重 w[i]，价值 v[i]。
 * 背包容量为 C，每种物品最多选 1 个，求最大总价值。
 *
 * 为什么学这个？
 * 0/1 背包是 DP 最重要的模型！没有之一。
 * 它是"选/不选"决策的经典代表。
 * 后面很多问题（子集、分割等和子集、目标总和）都是它的变体。
 *
 * 思路：
 *  状态定义：dp[i][c] = 前 i 个物品中，容量为 c 时的最大价值
 *  转移方程：
 *    不选第 i 个物品：dp[i][c] = dp[i-1][c]
 *    选第 i 个物品：  dp[i][c] = dp[i-1][c-w[i]] + v[i]  （前提 c >= w[i]）
 *    取二者最大值
 *  边界：dp[0][c] = 0（没有物品可选）
 *
 *  空间优化：用一维数组，容量从大到小遍历（防止重复选）
 */

// ─── 基础版：二维数组 ──────────────────────────────────
function knapsack01(weights: number[], values: number[], capacity: number): number {
  const n = weights.length;
  // dp[i][c] = 前 i 个物品，容量 c 的最大价值
  const dp: number[][] = Array.from({ length: n + 1 }, () => Array(capacity + 1).fill(0));

  for (let i = 1; i <= n; i++) {
    const w = weights[i - 1];
    const v = values[i - 1];
    for (let c = 0; c <= capacity; c++) {
      // 不选第 i 个物品
      dp[i][c] = dp[i - 1][c];
      // 如果放得下，尝试选第 i 个物品
      if (c >= w) {
        dp[i][c] = Math.max(dp[i][c], dp[i - 1][c - w] + v);
      }
    }
  }

  return dp[n][capacity];
}

// ─── 空间优化版：一维数组，容量倒序遍历 ────────────────
// 关键：为什么容量要倒序？
//   dp[c] 在更新时，dp[c-w] 必须是"上一行"的值
//   如果从左到右，dp[c-w] 已经被当前行更新了，相当于"选了多次"
//   从右到左，保证 dp[c-w] 还是上一行的值
function knapsack01Opt(weights: number[], values: number[], capacity: number): number {
  const n = weights.length;
  const dp: number[] = Array(capacity + 1).fill(0);

  for (let i = 0; i < n; i++) {
    const w = weights[i];
    const v = values[i];
    // 容量从大到小遍历
    for (let c = capacity; c >= w; c--) {
      dp[c] = Math.max(dp[c], dp[c - w] + v);
    }
  }

  return dp[capacity];
}

// ─── 测试 ──────────────────────────────────────────────
console.log('=== 0/1 背包问题 ===\n');

// 物品：重量 [2, 3, 4, 5]，价值 [3, 4, 5, 6]
// 容量 5：最优选 物品2(3重4价) + 物品1(2重3价) = 总价 7
const weights = [2, 3, 4, 5];
const values = [3, 4, 5, 6];
const capacities = [5, 8, 10];

for (const cap of capacities) {
  const r1 = knapsack01(weights, values, cap);
  const r2 = knapsack01Opt(weights, values, cap);
  console.log(`容量 ${cap}: 最大价值 = ${r1}（空间优化: ${r2}）`);
}

console.log('\n💡 关键认识：');
console.log('  0/1 背包 = 每个物品选/不选，容量维度倒序遍历');
console.log('  这是"选/不选"决策模型的原型');
console.log('  LeetCode 416(分割等和子集)、494(目标和) 都是它的变体');
console.log('\n  🔑 容量倒序的原因：');
console.log('    一维数组 dp[c] 存储的是"上一行"的值');
console.log('    如果正序遍历，dp[c-w] 会被当前行覆盖');
console.log('    相当于物品被选了多次（变成完全背包了）');

/**
 * 🎒 3-2 完全背包（Unbounded Knapsack）
 *
 * 问题：N 种物品，每种重 w[i]、价值 v[i]。背包容量 C，每种无限个。
 * 求最大总价值。
 *
 * 思路：
 *   dp[i][c] = max(dp[i-1][c], dp[i][c-w[i]] + v[i])
 *   选了 i 后还可以继续选 → 用 dp[i][c-w] 而不是 dp[i-1][c-w]
 *
 * 和 0/1 背包的唯一区别：容量遍历方向！
 *   0/1 背包：倒序（不能重复选）
 *   完全背包：正序（可以重复选）
 *
 * ────────────────────────────────────────────────────
 */

// ─── 二维 DP ──────────────────────────────────────
function unboundedKnapsack(weights: number[], values: number[], capacity: number): number {
  const n = weights.length;
  const dp: number[][] = Array.from({ length: n + 1 }, () => Array(capacity + 1).fill(0));
  for (let i = 1; i <= n; i++) {
    const w = weights[i - 1], v = values[i - 1];
    for (let c = 0; c <= capacity; c++) {
      dp[i][c] = dp[i - 1][c];
      if (c >= w) dp[i][c] = Math.max(dp[i][c], dp[i][c - w] + v);
    }
  }
  return dp[n][capacity];
}

// ─── 空间优化（一维，容量正序） ────────────────────
function unboundedKnapsackOpt(weights: number[], values: number[], capacity: number): number {
  const dp: number[] = Array(capacity + 1).fill(0);
  for (let i = 0; i < weights.length; i++) {
    const w = weights[i], v = values[i];
    for (let c = w; c <= capacity; c++) {
      dp[c] = Math.max(dp[c], dp[c - w] + v);
    }
  }
  return dp[capacity];
}

// ─── 测试 ─────────────────────────────────────────
console.log('=== 完全背包 ===\n');
const weights = [2, 3, 4], values = [3, 4, 5];
for (const cap of [5, 6, 10, 15]) {
  console.log(`容量 ${cap}: 最大价值 = ${unboundedKnapsack(weights, values, cap)}`);
}

/**
 * 🎒 3-3 零钱兑换（Coin Change）
 *
 * 问题：面额 coins[]（无限用），求组成 amount 的最少硬币数。
 * 无法组成则返回 -1。
 *
 * 思路：
 *   dp[a] = 组成金额 a 的最少硬币数
 *   dp[a] = min(dp[a], dp[a - c] + 1) 对每个硬币 c
 *   边界：dp[0] = 0，其他初始化为 Infinity
 *
 * 变体：
 *   组合数（LeetCode 518）：外循环硬币，内循环金额
 *   排列数（LeetCode 377）：外循环金额，内循环硬币
 *
 * ─── LeetCode 322 ─────────────────────────────────
 */

// ─── 最少硬币数 ──────────────────────────────────
function coinChange(coins: number[], amount: number): number {
  const dp: number[] = Array(amount + 1).fill(Infinity);
  dp[0] = 0;
  for (const coin of coins) {
    for (let a = coin; a <= amount; a++) {
      if (dp[a - coin] !== Infinity) {
        dp[a] = Math.min(dp[a], dp[a - coin] + 1);
      }
    }
  }
  return dp[amount] === Infinity ? -1 : dp[amount];
}

// ─── 组合数（LeetCode 518）──────────────────────────
function coinChangeCombinations(coins: number[], amount: number): number {
  const dp: number[] = Array(amount + 1).fill(0);
  dp[0] = 1;
  for (const coin of coins) {
    for (let a = coin; a <= amount; a++) {
      dp[a] += dp[a - coin];
    }
  }
  return dp[amount];
}

// ─── 排列数（LeetCode 377）──────────────────────────
function coinChangePermutations(coins: number[], amount: number): number {
  const dp: number[] = Array(amount + 1).fill(0);
  dp[0] = 1;
  for (let a = 1; a <= amount; a++) {
    for (const coin of coins) {
      if (a >= coin) dp[a] += dp[a - coin];
    }
  }
  return dp[amount];
}

// ─── 测试 ─────────────────────────────────────────
console.log('=== 零钱兑换 ===\n');
console.log('coins=[1,2,5], amount=11 →', coinChange([1,2,5], 11), '(期望 3: 5+5+1)');
